{
  "title": "CSCI-541: Programming Foundations Blueprint",
  "learningObjectives": [
    "Identify the core components of a programming paradigm and language as defined in the course catalog.",
    "Apply problem-solving methods including precise statements, algorithms, and decomposition to construct solutions.",
    "Utilize Python-specific concepts such as namespaces, exceptions, and data models to reason about program behavior."
  ],
  "beats": [
    {
      "title": "Course Scope and Paradigm Selection",
      "claim": "The course introduces students to a programming paradigm and an appropriate language chosen from those currently important or showing high promise.",
      "example": "Students might select a paradigm like object-oriented programming paired with Python for a semester-long project.",
      "visualDirection": "Display the official catalog description text highlighting the goal of introducing a paradigm and language.",
      "sourceIds": ["rit-csci-541"]
    },
    {
      "title": "Prerequisites and Credit Policy",
      "claim": "Prerequisites include CSCI-344 or equivalent, and the course can be taken for credit more than once if each instance deals with a different paradigm and language.",
      "example": "A student who completed CSCI-344 could enroll in CSCI-541 for Python, then later enroll again for a different language like Java.",
      "visualDirection": "Show a checklist with 'CSCI-344 or equivalent' checked and a note about multi-credit eligibility under program coordinator approval.",
      "sourceIds": ["rit-csci-541"]
    },
    {
      "title": "Foundations of Problem Statements",
      "claim": "Programming begins with precise problem statements, input and output examples, and algorithms written independently of syntax.",
      "example": "Before coding, a student writes a clear statement: 'Given a list of integers, return the sum of positive values.'",
      "visualDirection": "Render a text box containing a sample precise problem statement with defined inputs and expected outputs.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Core Computational Concepts",
      "claim": "Variables represent values and state, expressions compute values, and control structures select or repeat operations.",
      "example": "Using a variable `count` to track iterations in a loop that repeats a calculation ten times.",
      "visualDirection": "Diagram showing a variable box, an expression arrow, and a flowchart with a loop structure.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Decomposition via Functions",
      "claim": "Functions decompose a solution into named operations with parameters and results.",
      "example": "Defining a function `calculate_average(numbers)` that takes a list and returns a float.",
      "visualDirection": "Illustrate a function definition block with parameters on the left and a return value on the right.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Recursion and Base Cases",
      "claim": "Recursion solves a problem through smaller instances and requires a base case to terminate.",
      "example": "A factorial function that calls itself with `n-1` until `n` equals 0.",
      "visualDirection": "Show a recursive call stack diagram with a highlighted base case at the bottom.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Data Structures Overview",
      "claim": "Lists represent ordered sequences, stacks use last-in first-out access, queues use first-in first-out access, trees represent hierarchy, and graphs represent connected entities.",
      "example": "Using a stack to manage undo operations in a text editor.",
      "visualDirection": "Present icons or simple diagrams for a list, stack, queue, tree, and graph labeled with their access patterns.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Python Language Mechanics",
      "claim": "Python objects have identity, a type, and a value; names are bound to objects within namespaces and scopes.",
      "example": "Assigning `x = 5` binds the name `x` to an integer object with identity `id(x)`.",
      "visualDirection": "Display a Python REPL snippet showing object identity and namespace binding.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Control Flow and Exceptions",
      "claim": "Exceptions interrupt normal control flow until a matching handler processes them or they propagate.",
      "example": "A `try/except` block catching a `ZeroDivisionError` when dividing by zero.",
      "visualDirection": "Flowchart illustrating normal execution path versus an exception path leading to a handler.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Analysis and Debugging Checklist",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases.",
      "example": "Writing unit tests that cover edge cases like empty lists or maximum integer values.",
      "visualDirection": "Render a checklist titled 'Verification Steps' with items: Write tests, Trace execution, Compare results, Handle errors.",
      "sourceIds": ["opendsa-programming-foundations"]
    }
  ]
}
